  protected handleSpecialCollected(
    poop: Phaser.Physics.Arcade.Sprite,
    type: import('../abilities/types').SpecialPoopType,
    baseScore: number,
    emoji: string,
    color: string,
    counterIncrement: () => void,
  ) {
    if (this.gameOver) return;
    (poop as PoolablePoopBase).recycle();
    counterIncrement();
    const bonus = this.ability.onCollectSpecial(type) + (this.activeSynergy?.collectBonus ?? 0);
    const total = baseScore + bonus;
    this.collectBonusTotal += bonus;
    this.updateScore(total);
    if (!this.isFeverTime) {
      const suffix = bonus > 0 ? ` (+${bonus})` : '';
      const t = this.add.text(this.scale.width / 2, 100, `${emoji} +${total}점!${suffix} ${emoji}`, {
        fontSize: '28px', color, fontStyle: 'bold',
        stroke: '#000', strokeThickness: 4,
        padding: { top: 6 },
      }).setOrigin(0.5);
      this.time.delayedCall(1000, () => t.destroy());
    }
  }

  private handleTopazCollected(poop: Phaser.Physics.Arcade.Sprite, scoreMultiplier = 1) {
    this.handleSpecialCollected(poop, 'topaz', Math.round(80 * scoreMultiplier), '⭐', '#FFC300', () => { this.topazCollected++; });
  }

  private collectTopazPoop(
    _player: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile,
    _topazPoop: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile
  ) {
    this.handleTopazCollected(_topazPoop as TopazPoop);
  }

  private handleRainbowCollected(poop: Phaser.Physics.Arcade.Sprite) {
    this.handleSpecialCollected(poop, 'rainbow', 90, '🌈', '#FF00FF', () => { this.rainbowCollected++; });
  }

  private collectRainbowPoop(
    _player: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile,
    _rainbowPoop: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile
  ) {
    this.handleRainbowCollected(_rainbowPoop as RainbowPoop);
  }

  /**
   * 점수를 증가시키고 보너스 아이템 생성을 체크합니다.
   * @param amount 증가할 점수 (기본값: 1)
   */
  protected updateScore(amount: number = 1) {
    if (!this.gameOver) {
      const oldScore = this.score;
      this.score += amount;
      this.scoreText.setText(`점수: ${this.score}`);

      // 실시간으로 최고 점수 갱신
      if (this.score > this.highScore) {
        this.highScore = this.score;
        this.highScoreText.setText(`최고: ${this.highScore}`);
      }

      // 점수 증가 범위 내에서 건너뛴 생성 포인트를 확인
      this.checkMissedSpawnPoints(oldScore, this.score);
    }
  }

  /**
   * 점수가 증가하는 동안 건너뛴 생성 포인트를 확인하고 생성
   * @param oldScore 이전 점수
   * @param newScore 새 점수
   */
  private checkMissedSpawnPoints(oldScore: number, newScore: number) {
    // 캐릭터별 스폰 간격 (노이즈는 단축)
    const intervals = this.ability.getSpawnIntervals();

    for (let score = oldScore + 1; score <= newScore; score++) {
      // 피버 타임 체크
      this.checkFeverTime(score);

      // 피버 타임 중이 아닐 때만 일반 금똥/다이아똥/토파즈똥 생성
      if (!this.isFeverTime) {
        if (score % intervals.gold === 0 && score > this.lastGoldPoopScore) {
          this.spawnGoldPoop();
          this.lastGoldPoopScore = score;
        }

        if (score % intervals.diamond === 0 && score > this.lastDiamondPoopScore) {
          this.spawnDiamondPoop();
          this.lastDiamondPoopScore = score;
        }

        if (score % intervals.topaz === 0 && score > this.lastTopazPoopScore) {
          this.spawnTopazPoop();
          this.lastTopazPoopScore = score;
        }
      }

      // 점수 기반 난이도 증가
      if (score % DIFFICULTY_SCALING.scoreInterval === 0) this.increaseDifficulty();

      // 매화×매화 시너지: 설정된 간격마다 화면의 모든 똥 제거
      if (
        this.activeSynergy?.clearPoops === true &&
        score % MAEHWA_PARAMS.synergyBurstInterval === 0 &&
        score > this.lastClearPoopsScore
      ) {
        this.lastClearPoopsScore = score;
        this.clearAllPoopsWithEffect();
      }

      // 캐릭터 능력 마일스톤 (광부 무지개똥, 루트 똥 제거, 매화 슬래시 등)
      this.ability.onScoreMilestone(score, this.abilityAPI);
    }
  }

  /** spawnTimer를 현재 난이도 delay로 교체하는 헬퍼 */
  private resetSpawnTimer(callback: () => void) {
    this.spawnTimer.remove();
    this.spawnTimer = this.time.addEvent({
      delay: this.currentSpawnDelay,
      callback,
      callbackScope: this,
      loop: true
    });
  }

  private increaseDifficulty() {
    this.difficultyLevel += DIFFICULTY_SCALING.levelIncrement;
    this.resetSpawnTimer(
      this.isFeverTime
        ? (this.isRainbowFever ? this.spawnRainbowFeverPoop : this.spawnFeverPoop)
        : this.spawnPoop
    );
  }

  /**
   * 피버 타임 발동 조건 체크 (설정 기반)
   */
  private checkFeverTime(score: number) {
    if (score < FEVER_TIME_CONFIG.firstTriggerScore) return;

    // 가변 간격으로 피버 트리거 점수 누산
    // gap(k) = baseInterval + floor((k-1) / intervalIncreaseEvery) * intervalIncrement
    const { firstTriggerScore, baseInterval, intervalIncrement, intervalIncreaseEvery } = FEVER_TIME_CONFIG;
    let feverScore = firstTriggerScore;
    let lastFeverScore = feverScore;
    let k = 1;
    while (feverScore <= score) {
      lastFeverScore = feverScore;
      const gap = baseInterval + Math.floor((k - 1) / intervalIncreaseEvery) * intervalIncrement;
      feverScore += gap;
      k++;
    }

    if (this.lastFeverTimeScore < lastFeverScore) {
      this.startFeverTime();
      this.lastFeverTimeScore = lastFeverScore;
    }
  }

  /**
   * 피버 타임 시작 (기존 똥을 보너스 아이템으로 변환)
   */
  private startFeverTime() {
    if (this.gameOver) return;

    this.isFeverTime = true;
    this.feverTimeRemaining = FEVER_TIME_CONFIG.duration;

    // 레인보우 피버: 시너지에 rainbowFever 플래그가 있고 2번째 피버부터 4회마다 (2, 6, 10...)
    this.feverCount++;
    const isRainbowFeverNow =
      this.activeSynergy?.rainbowFever === true &&
      this.feverCount >= 2 &&
      (this.feverCount - 2) % 4 === 0;
    this.isRainbowFever = isRainbowFeverNow;

    // 기존 화면 위 똥들 처리
    if (isRainbowFeverNow) {
      // 레인보우 피버: 모든 기존 똥(일반+금+다이아)을 무지개똥으로 변환
      const positions: Array<{ x: number; y: number; velocity: number }> = [];

      this.poops.children.entries.forEach((poop) => {
        const s = poop as Poop;
        if (!s.active) return;
        const body = s.body as Phaser.Physics.Arcade.Body;
        if (!body) return;
        positions.push({ x: s.x, y: s.y, velocity: body.velocity.y });
        s.recycle();
      });
      [this.goldPoops, this.diamondPoops].forEach((group) => {
        group.children.entries.forEach((item) => {
          const s = item as PoolablePoopBase;
          if (!s.active) return;
          const body = s.body as Phaser.Physics.Arcade.Body;
          if (!body) return;
          positions.push({ x: s.x, y: s.y, velocity: body.velocity.y });
          s.recycle();
        });
      });

      positions.forEach((pos) => {
        for (let b = 0; b < 7; b++) {
          const r = Phaser.Math.Between(3, 7);
          const startX = pos.x + Phaser.Math.Between(-10, 10);
          const bubble = this.add.circle(startX, pos.y, r, GameScene.BUBBLE_COLORS[b % GameScene.BUBBLE_COLORS.length], 0.9).setDepth(200);
          this.tweens.add({
            targets: bubble,
            x: startX + Phaser.Math.Between(-18, 18),
            y: pos.y - Phaser.Math.Between(28, 55),
            alpha: 0,
            scaleX: 0.2,
            scaleY: 0.2,
            duration: Phaser.Math.Between(280, 480),
            ease: 'Sine.easeOut',
            delay: b * 20,
            onComplete: () => bubble.destroy(),
          });
        }

        const rp = this.rainbowPoops.get() as RainbowPoop;
        if (!rp) return;
        rp.reinit(pos.x, pos.y);
        if (rp.body) {
          rp.body.velocity.y = pos.velocity * FEVER_TIME_CONFIG.speedMultiplier;
        }
      });
    } else {
      // 일반 피버: 기존 일반 똥 → 금똥/다이아똥 변환
      if (this.poops) {
        const poopPositions: Array<{ x: number; y: number; velocity: number }> = [];

        this.poops.children.entries.forEach((poop) => {
          const poopSprite = poop as Poop;
          if (!poopSprite.active) return;
          const body = poopSprite.body as Phaser.Physics.Arcade.Body;
          if (!body) return;
          poopPositions.push({ x: poopSprite.x, y: poopSprite.y, velocity: body.velocity.y });
          poopSprite.recycle();
        });

        poopPositions.forEach((pos) => {
          const isGold = Math.random() < 0.5;
          if (isGold) {
            const goldPoop = this.goldPoops.get() as GoldPoop;
            if (goldPoop) {
              goldPoop.reinit(pos.x, pos.y);
              if (goldPoop.body) {
                goldPoop.body.velocity.y = pos.velocity * FEVER_TIME_CONFIG.speedMultiplier;
              }
            }
          } else {
            const diamondPoop = this.diamondPoops.get() as DiamondPoop;
            if (diamondPoop) {
              diamondPoop.reinit(pos.x, pos.y);
              if (diamondPoop.body) {
                diamondPoop.body.velocity.y = pos.velocity * FEVER_TIME_CONFIG.speedMultiplier;
              }
            }
          }
        });
      }

      // 기존 금똥/다이아똥 속도만 증가
      [this.goldPoops, this.diamondPoops].forEach((group) => {
        group.children.entries.forEach((item) => {
          const s = item as PoolablePoopBase;
          if (s.body) s.body.velocity.y *= FEVER_TIME_CONFIG.speedMultiplier;
        });
      });
    }

    // spawnTimer를 피버 타임 생성 패턴으로 교체
    this.resetSpawnTimer(isRainbowFeverNow ? this.spawnRainbowFeverPoop : this.spawnFeverPoop);

    // UI 텍스트 생성 (각 글자별로 개별 Text 객체 생성)
    // 기존 텍스트 제거
    this.feverTimeUITexts.forEach((text) => text.destroy());
    this.feverTimeUITexts = [];
    this.feverTimeColorOffset = 0;

    const initialSeconds = Math.ceil(FEVER_TIME_CONFIG.duration / 1000);
    const fullText = `${this.feverTimeLabel} ${initialSeconds}초`;

    // 각 글자별로 Text 객체 생성 (x=0에 먼저 배치 후 width 합산해 재정렬)
    const colors = isRainbowFeverNow ? GameScene.NEON_RAINBOW_COLORS : GameScene.RAINBOW_COLORS;
    const uiFontSize = isRainbowFeverNow ? '22px' : FEVER_TIME_CONFIG.ui.fontSize;
    const uiStroke  = isRainbowFeverNow ? '#cc00ff' : FEVER_TIME_CONFIG.ui.stroke;
    const uiStrokeThickness = isRainbowFeverNow ? 5 : FEVER_TIME_CONFIG.ui.strokeThickness;

    for (let i = 0; i < fullText.length; i++) {
      const charText = this.add.text(
        0,
        FEVER_TIME_CONFIG.ui.position.y,
        fullText[i],
        {
          fontSize: uiFontSize,
          color: colors[i % colors.length],
          fontStyle: 'bold',
          stroke: uiStroke,
          strokeThickness: uiStrokeThickness,
          shadow: isRainbowFeverNow
            ? { offsetX: 0, offsetY: 0, color: colors[i % colors.length], blur: 8, stroke: true, fill: true }
            : undefined,
        }
      ).setOrigin(0, 0.5).setDepth(FEVER_TIME_CONFIG.ui.depth);
      this.feverTimeUITexts.push(charText);
    }

    // 생성된 Text 객체의 width를 합산해 중앙 정렬
    const totalWidth = this.feverTimeUITexts.reduce((sum, t) => sum + t.width, 0);
    let currentX = this.scale.width / 2 - totalWidth / 2;
    for (const charText of this.feverTimeUITexts) {
      charText.setX(currentX);
      currentX += charText.width;
    }

    // 레인보우 피버: 글자마다 파도치는 bounce 애니메이션
    if (isRainbowFeverNow) {
      this.feverTimeUITexts.forEach((charText, i) => {
        this.tweens.add({
          targets: charText,
          y: FEVER_TIME_CONFIG.ui.position.y - 10,
          duration: 260,
          ease: 'Sine.easeInOut',
          yoyo: true,
          repeat: -1,
          delay: i * 38,
        });
      });
    }



    // 카운트다운 타이머
    if (this.feverTimeTimer) {
      this.feverTimeTimer.remove();
    }
    this.feverTimeTimer = this.time.addEvent({
      delay: 100,
      callback: this.updateFeverTime,
      callbackScope: this,
      loop: true
    });

    // 색상 애니메이션 타이머 (0.2초마다 색상 한 칸 이동)
    if (this.feverTimeColorTimer) {
      this.feverTimeColorTimer.remove();
    }
    this.feverTimeColorTimer = this.time.addEvent({
      delay: isRainbowFeverNow ? 80 : 200,
      callback: this.updateFeverTimeColors,
      callbackScope: this,
      loop: true
    });
  }

  /**
   * 피버 타임 카운트다운 업데이트
   */
  private updateFeverTime() {
    this.feverTimeRemaining -= 100; // 0.1초씩 감소

    const secondsRemaining = Math.ceil(this.feverTimeRemaining / 1000);
    const newText = `${this.feverTimeLabel} ${secondsRemaining}초`;

    // 각 글자의 텍스트 내용 업데이트
    for (let i = 0; i < this.feverTimeUITexts.length; i++) {
      if (i < newText.length) {
        this.feverTimeUITexts[i].setText(newText[i]);
      }
    }

    // 텍스트 길이가 변경된 경우 (초 카운트 변경) 위치 재조정
    if (this.feverTimeUITexts.length > 0) {
      // setText() 후 width가 즉시 갱신되므로 별도 측정 객체 불필요
      const totalWidth = this.feverTimeUITexts.reduce((sum, t) => sum + t.width, 0);
      let currentX = this.scale.width / 2 - totalWidth / 2;
      for (let i = 0; i < this.feverTimeUITexts.length && i < newText.length; i++) {
        this.feverTimeUITexts[i].setX(currentX);
        currentX += this.feverTimeUITexts[i].width;
      }
    }

    // 시간이 다 떨어지면 피버 타임 종료
    if (this.feverTimeRemaining <= 0) {
      this.endFeverTime();
    }
  }

  /**
   * 피버 타임 색상 애니메이션 업데이트
   */
  private updateFeverTimeColors() {
    const colors = this.isRainbowFever ? GameScene.NEON_RAINBOW_COLORS : GameScene.RAINBOW_COLORS;
    this.feverTimeColorOffset = (this.feverTimeColorOffset - 1 + colors.length) % colors.length;
    for (let i = 0; i < this.feverTimeUITexts.length; i++) {
      this.feverTimeUITexts[i].setColor(colors[(i + this.feverTimeColorOffset) % colors.length]);
    }
  }

  /**
   * 피버 타임 종료
   */
  /** 피버 타임 UI/타이머 정리 (spawnTimer 재설정 없음). 비활성 상태면 no-op. */
  private clearFeverTimeUI() {
    if (!this.isFeverTime) return;
    this.isFeverTime = false;
    this.isRainbowFever = false;
    this.feverTimeTimer?.remove();
    this.feverTimeColorTimer?.remove();
    this.feverTimeUITexts.forEach(t => { this.tweens.killTweensOf(t); t.destroy(); });
    this.feverTimeUITexts = [];
  }

  private endFeverTime() {
    this.clearFeverTimeUI();

    // 일반 생성 패턴으로 복구
    this.resetSpawnTimer(this.spawnPoop);
  }

  /**
   * 피버 타임 생성 패턴 (설정 기반, 속도 증가)
   */
  private spawnFeverPoop() {
    if (this.gameOver) return;

    const baseFallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement);

    // 1. 일반 똥 생성 (피버 타임 속도 배수 적용)
    const normalFallSpeed = baseFallSpeed * FEVER_TIME_CONFIG.speedMultiplier;
    for (let i = 0; i < FEVER_TIME_CONFIG.normalPoopCount; i++) {
      const x = Phaser.Math.Between(15, this.scale.width - 15);
      const y = Phaser.Math.Between(-200, -20);
      const poop = this.poops.get() as Poop;
      if (!poop) continue;
      poop.reinit(x, y, this.difficulty);
      if (poop.body) {
        poop.body.velocity.y = normalFallSpeed;
      }
    }

    // 2. 금똥/다이아똥 랜덤 생성 (피버 타임 속도 배수 적용)
    for (let i = 0; i < FEVER_TIME_CONFIG.bonusPoopCount; i++) {
      const x = Phaser.Math.Between(50, this.scale.width - 50);
      const y = Phaser.Math.Between(-200, -50);

      // 50% 확률로 금똥 또는 다이아똥 결정
      const isGold = Math.random() < 0.5;

      if (isGold) {
        const goldPoop = this.goldPoops.get() as GoldPoop;
        if (goldPoop) {
          goldPoop.reinit(x, y);
          if (goldPoop.body) {
            goldPoop.body.velocity.y = (baseFallSpeed - POOP_CONFIG.gold.speedReduction) * FEVER_TIME_CONFIG.speedMultiplier;
          }
        }
      } else {
        const diamondPoop = this.diamondPoops.get() as DiamondPoop;
        if (diamondPoop) {
          diamondPoop.reinit(x, y);
          if (diamondPoop.body) {
            diamondPoop.body.velocity.y = (baseFallSpeed - POOP_CONFIG.diamond.speedReduction) * FEVER_TIME_CONFIG.speedMultiplier;
          }
        }
      }
    }

    this.ability.onAfterSpawnPoop(this.abilityAPI);
  }

  /**
   * 레인보우 피버 생성 패턴 — 무지개똥만 소환 (광부×황금광산 시너지)
   */
  private spawnRainbowFeverPoop() {
    if (this.gameOver) return;

    const baseFallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement);
    const fallSpeed = baseFallSpeed * FEVER_TIME_CONFIG.speedMultiplier;
    const totalCount = FEVER_TIME_CONFIG.normalPoopCount + FEVER_TIME_CONFIG.bonusPoopCount;

    for (let i = 0; i < totalCount; i++) {
      const x = Phaser.Math.Between(50, this.scale.width - 50);
      const y = Phaser.Math.Between(-200, -20);
      const rp = this.rainbowPoops.get() as RainbowPoop;
      if (!rp) continue;
      rp.reinit(x, y);
      if (rp.body) {
        rp.body.velocity.y = fallSpeed;
      }
    }
  }

  /**
   * 매화×매화 시너지: 화면의 모든 똥 제거 + 매화 꽃잎 폭발 이펙트
   */
  private clearAllPoopsWithEffect(): void {
    if (this.gameOver) return;

    // 모든 그룹의 활성 오브젝트 수집 (위치 기록 후 제거)
    const positions: Array<{ x: number; y: number }> = [];

    const collectGroup = (group: Phaser.Physics.Arcade.Group, handler: (sp: Phaser.Physics.Arcade.Sprite) => void) => {
      [...group.children.entries].forEach(obj => {
        const sp = obj as Phaser.Physics.Arcade.Sprite;
        if (sp.active) { positions.push({ x: sp.x, y: sp.y }); handler(sp); }
      });
    };

    // 일반 똥: recycle만, 특수 똥: 핸들러 호출 → recycle + 점수
    collectGroup(this.poops, sp => (sp as unknown as PoolablePoopBase).recycle());
    collectGroup(this.goldPoops,   sp => this.handleGoldCollected(sp));
    collectGroup(this.diamondPoops, sp => this.handleDiamondCollected(sp));
    collectGroup(this.topazPoops,  sp => this.handleTopazCollected(sp));

    const effectPositions = positions.length > 0 ? positions : [{ x: 200, y: 300 }];
    effectPositions.forEach(pos => this.spawnMaehwaBurst(pos.x, pos.y));

    // 화면 전체 분홍빛 플래시 — setScrollFactor(0)으로 카메라 독립, 오브젝트 alpha로 fade 제어
    const flash = this.add.graphics().setDepth(200).setAlpha(0.3).setScrollFactor(0);
    flash.fillStyle(0xff6699, 1);
    flash.fillRect(0, 0, this.scale.width, this.scale.height);
    this.tweens.add({
      targets: flash,
      alpha: 0,
      duration: 500,
      ease: 'Quad.easeIn',
      onComplete: () => flash.destroy(),
    });
  }

  /** 매화 꽃잎 폭발 — 한 지점에서 칼날 이펙트 + 꽃잎 여러 장 사방으로 비산 */
  private spawnMaehwaBurst(cx: number, cy: number): void {
    // 칼날 이펙트 (↗ 방향 마름모꼴)
    const slash = this.add.graphics().setDepth(195);
    const len = 26, wid = 7;
    slash.fillStyle(0xff3366, 0.9);
    slash.fillPoints([
      new Phaser.Geom.Point(cx - len, cy + len),
      new Phaser.Geom.Point(cx - wid * 0.4, cy + wid),
      new Phaser.Geom.Point(cx + len, cy - len),
      new Phaser.Geom.Point(cx + wid * 0.4, cy - wid),
    ], true);
    slash.lineStyle(3, 0xffffff, 0.5);
    slash.lineBetween(cx - len, cy + len, cx + len, cy - len);
    this.tweens.add({ targets: slash, alpha: 0, duration: 300, onComplete: () => slash.destroy() });

    const COUNT = 10;
    for (let i = 0; i < COUNT; i++) {
      const petal = this.add.graphics().setDepth(190);
      petal.setPosition(cx, cy);
      const w = Phaser.Math.Between(4, 8);
      const h = Phaser.Math.Between(7, 12);
      petal.fillStyle(0xff3377, 0.9);
      petal.fillEllipse(0, 0, w, h);
      petal.setAngle(Phaser.Math.Between(0, 360));

      const angle = Phaser.Math.Between(0, 360);
      const dist  = Phaser.Math.Between(40, 90);
      this.tweens.add({
        targets: petal,
        x: cx + Math.cos(Phaser.Math.DegToRad(angle)) * dist,
        y: cy + Math.sin(Phaser.Math.DegToRad(angle)) * dist + Phaser.Math.Between(20, 50),
        angle: petal.angle + Phaser.Math.Between(-180, 180),
        alpha: 0,
        duration: Phaser.Math.Between(500, 900),
        ease: 'Quad.easeOut',
        onComplete: () => petal.destroy(),
      });
    }
  }

  protected hitPoop(
    _player: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile,
    poop: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile
  ) {
    if (this.gameOver) return;
    if (this.player.getIsInvincible()) return;

    // 센티넬: 보호막이 있으면 게임오버 대신 보호막 소모 + 똥 반환
    if (this.ability.onHitPoop(this.abilityAPI)) {
      (poop as unknown as PoolablePoopBase).recycle();
      return;
    }

    this.gameOver = true;
    this.manualHitboxDebug?.clear();
    this.ability.onDestroy(this.abilityAPI);
    this.clearFeverTimeUI();
    this.spawnTimer.remove();
    this.physics.pause();

    // 점수 검증 데이터 로그
    const gameEndTime = realNow();
    const playDuration = gameEndTime - this.gameStartTime;
    const bonusScore = this.goldCollected * 20 + this.diamondCollected * 40 + this.topazCollected * 80 + this.rainbowCollected * 90;
    const timeScore = Math.floor(playDuration / 100); // 100ms당 1점
    const expectedScore = timeScore + bonusScore;
    const phaserTime = this.time.now - this.phaserStartTime; // 이번 게임의 Phaser 경과 시간
    const timeRatio = phaserTime / playDuration;
    console.log('[점수 검증 데이터]', {
      최종점수: this.score,
      시간점수: timeScore,
      보너스점수: bonusScore,
      예상점수: expectedScore,
      점수차이: this.score - expectedScore,
      현실시간: `${(playDuration / 1000).toFixed(1)}초`,
      Phaser시간: `${(phaserTime / 1000).toFixed(1)}초`,
      시간비율: timeRatio.toFixed(2),
      금똥: this.goldCollected,
      다이아똥: this.diamondCollected,
      토파즈똥: this.topazCollected,
      무지개똥: this.rainbowCollected,
    });

    // 최고 점수 업데이트 및 갱신 여부 확인
    const isNewRecord = updateHighScore(this.scoreDifficulty, this.score);

    // 게임 오버 UI 표시 (비동기 처리)
    this.showGameOverUI(isNewRecord);
  }

  private handleGoldCollected(poop: Phaser.Physics.Arcade.Sprite, scoreMultiplier = 1) {
    this.handleSpecialCollected(poop, 'gold', Math.round(20 * scoreMultiplier), '💰', '#FFD700', () => { this.goldCollected++; });
  }

  private collectGoldPoop(
    _player: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile,
    _goldPoop: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile
  ) {
    this.handleGoldCollected(_goldPoop as GoldPoop);
  }

  private handleDiamondCollected(poop: Phaser.Physics.Arcade.Sprite, scoreMultiplier = 1) {
    this.handleSpecialCollected(poop, 'diamond', Math.round(40 * scoreMultiplier), '💎', '#00FFFF', () => { this.diamondCollected++; });
  }

  private collectDiamondPoop(
    _player: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile,
    _diamondPoop: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile
  ) {
    this.handleDiamondCollected(_diamondPoop as DiamondPoop);
  }

  /**
   * 게임 오버 UI 표시 및 랭킹 시스템 연동
   */
  protected async showGameOverUI(isNewRecord: boolean) {
    const W = this.scale.width;
    const H = this.scale.height;
    const cx = W / 2;
    // 반투명 검정 배경 추가 (가독성 향상)
    this.add.rectangle(cx, H / 2, W, H, 0x000000, 0.7).setDepth(200);

    // SKOR 제출 (백그라운드, 모든 모드에서 실행)
    // 새 기록 시: 이니셜 입력 영역(y≈380) 아래에 배치 / 일반 시: 개인최고(y≈320) 아래에 배치
    const skorStatusY = isNewRecord ? H / 2 + 118 : H / 2 + 80;
    const skorStatusText = this.add.text(cx, skorStatusY, '💰 SKOR 정제 중...', {
      fontSize: '16px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 2,
    }).setOrigin(0.5).setDepth(200);

    this.submitSkorOnGameOver(skorStatusText);

    if (isNewRecord) {
      // === 새 기록 달성 시: 상단에 배치 ===
      // 게임 오버 타이틀
      this.add.text(cx, H / 2 - 220, 'GAME OVER', {
        fontSize: '48px',
        color: '#ff0000',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 6
      }).setOrigin(0.5).setDepth(200);

      // 최종 점수
      this.add.text(cx, H / 2 - 150, `점수: ${this.score}`, {
        fontSize: '32px',
        color: '#ffffff',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 4
      }).setOrigin(0.5).setDepth(200);

      // 새 기록 메시지
      this.add.text(cx, H / 2 - 100, '🎉 개인 신기록 🎉', {
        fontSize: '28px',
        color: '#FFD700',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 4,
        padding: { top: 6 },
      }).setOrigin(0.5).setDepth(200);

      // 이니셜 입력 UI 표시
      this.showInitialInputUI();
    } else {
      // === 새 기록 미달성 시: 중앙에 배치 ===
      // 게임 오버 타이틀
      this.add.text(cx, H / 2 - 120, 'GAME OVER', {
        fontSize: '48px',
        color: '#ff0000',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 6
      }).setOrigin(0.5).setDepth(200);

      // 최종 점수
      this.add.text(cx, H / 2 - 40, `점수: ${this.score}`, {
        fontSize: '32px',
        color: '#ffffff',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 4
      }).setOrigin(0.5).setDepth(200);

      // 로컬 최고 점수
      this.add.text(cx, H / 2 + 20, `개인 최고: ${this.highScore}`, {
        fontSize: '24px',
        color: '#FFD700',
        stroke: '#000000',
        strokeThickness: 3
      }).setOrigin(0.5).setDepth(200);

      // 재시작 안내
      this.showRestartButton(false);
    }
  }

  /**
   * 이니셜 입력 UI 표시
   */
  private showInitialInputUI() {
    const W = this.scale.width;
    const H = this.scale.height;
    const cx = W / 2;
    // 안내 텍스트
    this.add.text(cx, H / 2 - 50, '이니셜 입력 (영어 대문자 3자)', {
      fontSize: '18px',
      color: '#ffffff',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 3
    }).setOrigin(0.5).setDepth(200);

    // HTML input 엘리먼트 생성
    const inputElement = document.createElement('input');
    inputElement.type = 'text';
    inputElement.maxLength = 3;
    inputElement.placeholder = 'ABC';

    // 캔버스 실제 위치·스케일에 맞춰 input 좌표 계산
    // (Phaser FIT 스케일 모드에서 캔버스가 이동/축소될 수 있으므로 DOM 좌표계와 동기화)
    const canvas = this.game.canvas;
    const rect = canvas.getBoundingClientRect();
    const gameW = this.scale.width;
    const gameH = this.scale.height;
    const scaleX = rect.width / gameW;
    const scaleY = rect.height / gameH;
    // 게임 좌표 (cx, H/2-15) → viewport 픽셀 좌표로 변환
    const screenLeft = rect.left + (gameW / 2) * scaleX;
    const screenTop  = rect.top  + (gameH / 2 - 15) * scaleY;

    inputElement.style.cssText = `
      position: fixed;
      left: ${screenLeft}px;
      top: ${screenTop}px;
      transform: translateX(-50%);
      width: ${Math.round(130 * scaleX)}px;
      height: ${Math.round(44 * scaleY)}px;
      font-size: ${Math.round(22 * scaleY)}px;
      text-align: center;
      text-transform: uppercase;
      border: ${Math.max(2, Math.round(3 * scaleY))}px solid #FFD700;
      border-radius: 8px;
      background: #000;
      color: #fff;
      font-weight: bold;
      letter-spacing: ${Math.round(6 * scaleX)}px;
      outline: none;
      box-sizing: border-box;
      z-index: 9999;
    `;

    // 기존 이니셜이 있으면 미리 채우기
    const existingInitials = getUserInitials();
    if (existingInitials) {
      inputElement.value = existingInitials;
    }

    document.body.appendChild(inputElement);
    inputElement.focus();

    // 대문자만 입력되도록
    inputElement.addEventListener('input', (e) => {
      const target = e.target as HTMLInputElement;
      target.value = target.value.toUpperCase().replace(/[^A-Z]/g, '');
    });

    // 제출 버튼 텍스트
    const submitButtonText = this.add.text(cx, H / 2 + 75, '랭킹 등록', {
      fontSize: '24px',
      color: '#00ff00',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4,
      padding: { x: 20, y: 10 }
    }).setOrigin(0.5).setInteractive().setDepth(200);

    // 에러 메시지 영역
    let errorText: Phaser.GameObjects.Text | null = null;

    // 제출 버튼 클릭
    submitButtonText.on('pointerdown', async () => {
      const initials = inputElement.value.trim().toUpperCase();

      // 검증
      if (initials.length !== 3) {
        if (errorText) errorText.destroy();
        errorText = this.add.text(cx, H / 2 + 120, '정확히 3글자를 입력하세요', {
          fontSize: '16px',
          color: '#ff0000',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3
        }).setOrigin(0.5).setDepth(200);
        return;
      }

      if (!/^[A-Z]{3}$/.test(initials)) {
        if (errorText) errorText.destroy();
        errorText = this.add.text(cx, H / 2 + 120, '영어 대문자만 입력하세요', {
          fontSize: '16px',
          color: '#ff0000',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3
        }).setOrigin(0.5).setDepth(200);
        return;
      }

      // 이니셜 저장
      setUserInitials(initials);

      // input 제거
      document.body.removeChild(inputElement);
      submitButtonText.destroy();
      if (errorText) errorText.destroy();

      // 랭킹 제출
      const submittingText = this.add.text(cx, H / 2, '랭킹 제출 중...', {
        fontSize: '18px',
        color: '#ffff00',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(0.5).setDepth(200);

      try {
        // 캐릭터 타입 결정 (이미 init()에서 검증된 값 사용)
        const characterType = this.selectedCharId;

        // 세션이 완료될 때까지 대기 (대부분 이미 완료되어 있음)
        const sessionId = await this.sessionPromise;

        const result = await submitScore(
          this.score,
          this.scoreDifficulty,
          initials,
          {
            gameStartTime: this.gameStartTime,
            gameEndTime: realNow(),
            goldCollected: this.goldCollected,
            diamondCollected: this.diamondCollected,
            topazCollected: this.topazCollected,
            rainbowCollected: this.rainbowCollected,
            collectBonusTotal: this.collectBonusTotal,
            abilityBonusTotal: this.abilityBonusTotal,
          },
          characterType,
          sessionId
        );

        submittingText.destroy();

        // 순위 표시
        if (result.rank !== null) {
          this.add.text(cx, H / 2 + 40, `🏆 전체 ${result.rank}위! 🏆`, {
            fontSize: '24px',
            color: '#FFD700',
            fontStyle: 'bold',
            stroke: '#000',
            strokeThickness: 3,
            padding: { top: 4 },
          }).setOrigin(0.5).setDepth(200);
        }

        // 이니셜 표시
        this.add.text(cx, H / 2 + 80, `${initials}`, {
          fontSize: '20px',
          color: '#00ff00',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3,
          letterSpacing: 4
        }).setOrigin(0.5).setDepth(200);

      } catch (error) {
        console.error('Failed to submit score:', error);
        submittingText.setText('❌ 랭킹 제출 실패');
        submittingText.setColor('#ff0000');
      }

      // 재시작 버튼 표시
      this.showRestartButton(true);
    });

    // Enter 키로도 제출 가능
    inputElement.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        submitButtonText.emit('pointerdown');
      }
    });
  }

  // 서버 getBracketCap과 동일 — 낙관적 UI 계산용 (서버 응답 전 예상값 표시)
  private getSkorBracketCap(score: number): number {
    if (score < 500)  return 20;
    if (score < 1000) return 45;
    if (score < 1500) return 80;
    if (score < 2000) return 115;
    if (score < 3000) return 160;
    if (score < 5000) return 215;
    return 280;
  }

  /**
   * 게임오버 시 SKOR 정제 수익 제출 및 화면 표시
   */
  private async submitSkorOnGameOver(statusText: Phaser.GameObjects.Text) {
    // ── 낙관적 UI: 서버 응답 전에 예상 SKOR 즉시 계산 ──
    const rawSkor =
      this.goldCollected * 0.5 +
      this.diamondCollected * 1.5 +
      this.topazCollected * 3.5 +
      this.rainbowCollected * 10.0;
    const estimatedSkor = Math.floor(Math.min(rawSkor, this.getSkorBracketCap(this.score)));

    // floor 후 0이면 API 호출 없이 즉시 종료 (퀘스트 진행도도 없음)
    if (estimatedSkor <= 0) {
      statusText.setText('💰 +0 SKOR (아이템 없음)');
      statusText.setColor('#888888');
      return;
    }

    statusText.setText(`💰 +${estimatedSkor} SKOR 획득!`);
    statusText.setColor('#FFD700');

    // ── 백그라운드 API 호출: 실제 결과로 보정 ──
    try {
      const result: SkorSubmitResponse = await submitSkor({
        score: this.score,
        goldCollected: this.goldCollected,
        diamondCollected: this.diamondCollected,
        topazCollected: this.topazCollected,
        rainbowCollected: this.rainbowCollected,
      });

      if (!this.scene.isActive()) return;

      // 주간 캡 소진 또는 실제값이 예상과 다른 경우만 갱신
      if (result.weeklyCapRemaining <= 0 && result.totalSkorAdded === 0) {
        statusText.setText(`💰 주간 한도 도달 (SKOR 없음)`);
        statusText.setColor('#888888');
      } else if (result.totalSkorAdded !== estimatedSkor) {
        statusText.setText(`💰 +${result.totalSkorAdded} SKOR 획득!`);
      }

      // 퀘스트 달성 시 추가 알림 (항상 표시)
      if (result.questRewards.length > 0) {
        const questLabels: Record<string, string> = {
          gold: '금똥', diamond: '다이아', topaz: '토파즈', rainbow: '무지개',
        };
        const questText = result.questRewards
          .map(r => `${questLabels[r.quest] ?? r.quest} 퀘스트 +${r.reward}`)
          .join(' / ');
        this.add.text(this.scale.width / 2, statusText.y + 23, `🎯 ${questText}`, {
          fontSize: '13px',
          color: '#88ff88',
          stroke: '#000',
          strokeThickness: 2,
          padding: { top: 3 },
        }).setOrigin(0.5).setDepth(200);
      }
    } catch {
      // 실패해도 낙관적으로 보여준 숫자 유지 (정제 결과는 서버에서 처리됨)
    }
  }

  /**
   * 재시작 버튼 표시 (다시 하기 + 메인 메뉴) - 버튼 스타일
   * @param isNewRecord 새 기록 달성 여부 (SKOR 텍스트 위치에 따라 버튼 y 조정)
   */
  private showRestartButton(isNewRecord = false) {
    const W = this.scale.width;
    const H = this.scale.height;
    const cx = W / 2;
    // 새 기록 시: SKOR 텍스트(H/2+118) + 퀘스트(+23) 아래 배치
    // 일반 시: SKOR 텍스트(H/2+80) + 퀘스트(+23) 아래 배치
    const retryY = isNewRecord ? H / 2 + 170 : H / 2 + 155;
    const menuY  = isNewRecord ? H / 2 + 248 : H / 2 + 235;

    // 다시 하기 버튼 배경
    const retryButtonBg = this.add.rectangle(cx, retryY, 250, 70, 0x00aa00)
      .setOrigin(0.5)
      .setDepth(199)
      .setStrokeStyle(3, 0xffffff);

    // 다시 하기 버튼 텍스트
    const retryButtonText = this.add.text(cx, retryY, '다시 하기', {
      fontSize: '22px',
      color: '#ffffff',
      fontStyle: 'bold'
    }).setOrigin(0.5).setDepth(200);

    // 다시 하기 버튼 인터랙티브 영역 (배경을 클릭 가능하게)
    retryButtonBg.setInteractive({ useHandCursor: true });

    // 메인 메뉴 버튼 배경
    const menuButtonBg = this.add.rectangle(cx, menuY, 250, 70, 0x555555)
      .setOrigin(0.5)
      .setDepth(199)
      .setStrokeStyle(3, 0xffffff);

    // 메인 메뉴 버튼 텍스트
    const menuButtonText = this.add.text(cx, menuY, '메인 메뉴', {
      fontSize: '22px',
      color: '#ffffff',
      fontStyle: 'bold'
    }).setOrigin(0.5).setDepth(200);

    // 메인 메뉴 버튼 인터랙티브 영역
    menuButtonBg.setInteractive({ useHandCursor: true });

    // 호버 효과 - 다시 하기 버튼
    retryButtonBg.on('pointerover', () => {
      retryButtonBg.setFillStyle(0x00ff00);
      retryButtonBg.setScale(1.05);
      retryButtonText.setScale(1.05);
    });
    retryButtonBg.on('pointerout', () => {
      retryButtonBg.setFillStyle(0x00aa00);
      retryButtonBg.setScale(1);
      retryButtonText.setScale(1);
    });

    // 호버 효과 - 메인 메뉴 버튼
    menuButtonBg.on('pointerover', () => {
      menuButtonBg.setFillStyle(0x777777);
      menuButtonBg.setScale(1.05);
      menuButtonText.setScale(1.05);
    });
    menuButtonBg.on('pointerout', () => {
      menuButtonBg.setFillStyle(0x555555);
      menuButtonBg.setScale(1);
      menuButtonText.setScale(1);
    });

    retryButtonBg.on('pointerdown', () => {
      const existingInput = document.querySelector('input');
      if (existingInput) document.body.removeChild(existingInput);
      this.sound.stopAll();
      if (this.player) this.player.cleanupEffects();
      this.scene.restart({ gameMode: this.gameMode, difficulty: this.difficulty, purePhysical: this.purePhysical });
    });

    menuButtonBg.on('pointerdown', () => {
      const existingInput = document.querySelector('input');
      if (existingInput) document.body.removeChild(existingInput);
      this.sound.stopAll();
      if (this.player) this.player.cleanupEffects();
      this.scene.start('ModeSelectScene');
    });
  }
}

