/** 화면 중앙에서 꽃잎이 회오리치며 바깥으로 퍼지는 vortex 이펙트 */
private spawnMaehwaVortex(): void {
  const cx = this.scale.width / 2;
  const cy = this.scale.height / 2;
  const COUNT = 14;

  // 안쪽 링 (작고 빠름) + 바깥쪽 링 (크고 느림) 두 레이어
  const layers = [
    { count: COUNT,      startR: 18, endR:  90, rotDeg: 360, duration: 800, petalW: [3, 6],  petalH: [7, 11], depth: 194 },
    { count: COUNT - 4,  startR: 35, endR: 140, rotDeg: -270, duration: 1100, petalW: [5, 8], petalH: [10, 15], depth: 192 },
  ];

  for (const layer of layers) {
    const container = this.add.container(cx, cy).setDepth(layer.depth);

    for (let i = 0; i < layer.count; i++) {
      const angle = (i / layer.count) * Math.PI * 2;

      const petal = this.add.graphics();
      petal.fillStyle(0xff3377, 0.8 + Math.random() * 0.2);
      petal.fillEllipse(0, 0, Phaser.Math.Between(layer.petalW[0], layer.petalW[1]), Phaser.Math.Between(layer.petalH[0], layer.petalH[1]));
      petal.setPosition(Math.cos(angle) * layer.startR, Math.sin(angle) * layer.startR);
      petal.setRotation(angle + Math.PI / 2);
      container.add(petal);

      this.tweens.add({
        targets: petal,
        x: Math.cos(angle) * layer.endR,
        y: Math.sin(angle) * layer.endR,
        alpha: 0,
        duration: layer.duration,
        ease: 'Sine.easeIn',
      });
    }

    this.tweens.add({
      targets: container,
      angle: layer.rotDeg,
      duration: layer.duration,
      ease: 'Quad.easeOut',
      onComplete: () => container.destroy(),
    });
  }
}

