    ease: 'Quad.easeIn',
    onUpdate: (tween) => {
      const global = tween.getValue();
      for (const { gfx, baseAngle, startT } of petals) {
        // 자신의 출발 시점 이전은 중심에 대기
        const t = Math.max(0, Math.min(1, (global - startT) / (1 - startT)));
        const angle  = baseAngle + t * Math.PI * 2 * TURNS;
        const radius = t * 150;
        gfx.setPosition(
          cx + Math.cos(angle) * radius,
          cy + Math.sin(angle) * radius,
        );
        gfx.setAngle(Phaser.Math.RadToDeg(angle) + 90);
        // 후반 35%에서 fade-out
        gfx.setAlpha(t < 0.65 ? 1 : 1 - (t - 0.65) / 0.35);
      }
    },
    onComplete: () => petals.forEach(p => p.gfx.destroy()),
  });
}

