    } else {
      // === 새 기록 미달성 시: 중앙에 배치 ===
      // 게임 오버 타이틀
      this.add.text(cx, H / 2 - 120, 'GAME OVER', {
        fontSize: '48px',
        color: '#ff0000',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 6
      }).setOrigin(0.5).setDepth(200);

      // 최종 점수
      this.add.text(cx, H / 2 - 40, `점수: ${this.score}`, {
        fontSize: '32px',
        color: '#ffffff',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 4
      }).setOrigin(0.5).setDepth(200);

      // 로컬 최고 점수
      this.add.text(cx, H / 2 + 20, `개인 최고: ${this.highScore}`, {
